@using RecipeShare.Services
@inject RecipeService Recipes

<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                title="Rate @star stars"
                disabled="@hasRated">
            @(star <= displayStars ? "★" : "☆")
        </button>
    }
    @if (hasRated)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
    @if (recipe is not null && recipe.RatingCount > 0)
    {
        <span class="ms-3 text-muted">
            Average: @recipe.AverageRating.ToString("F1") ⭐ (@recipe.RatingCount ratings)
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private Recipe? recipe;
    private int displayStars;
    private bool hasRated;

    protected override void OnParametersSet()
    {
        recipe = Recipes.GetById(RecipeId);
        displayStars = recipe is not null ? (int)Math.Round(recipe.AverageRating) : 0;
    }

    private void SubmitRating(int stars)
    {
        if (hasRated) return;
        Recipes.AddRating(RecipeId, stars);
        hasRated = true;
        displayStars = stars;
        recipe = Recipes.GetById(RecipeId);
    }
}

